/*
 * A320992  Expansion of (Product_{k>0} theta_4(q^k)/theta_3(q^k))^(1/2),
 *          where theta_3() and theta_4() are the Jacobi theta functions.
 * https://oeis.org/A320992
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  sign
 * Formula:   a(n) = coefficient of q^n in ∏_{k>0} θ₄(q^(2k-1))
 * Range:     i8 n <= 22, i16 n <= 66, i32 n <= 213, i64 n <= 733,
 *            i128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence can be generated by expanding the infinite product
 * ∏_{m odd ≥1} (1 - q^(2m)) (1 - q^m)^2.
 * For each exponent s, the multiplicity of the factor (1 - q^s) is
 *    c_s = τ_odd(s/2)          if s is even,
 *    c_s = 2 * τ_odd(s)          if s is odd,
 * where τ_odd(t) is the number of odd divisors of t.
 *
 * Once the multiplicities are known, the generating function is
 * ∏_s (1 - q^s)^{c_s}.  We compute the coefficients up to n by
 * repeatedly multiplying by (1 - q^s) a total of c_s times.
 */

#include <stdlib.h>
#include <stddef.h>

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)1;

    /* Allocate work arrays */
    size_t nn = (size_t)n;
    seq_t *dp = (seq_t *)calloc(nn + 1, sizeof(seq_t));
    if (!dp) return (seq_t)0;      /* allocation failure */
    dp[0] = (seq_t)1;

    /* odddiv[i] = number of odd divisors of i */
    int *odddiv = (int *)calloc(nn + 1, sizeof(int));
    if (!odddiv) { free(dp); return (seq_t)0; }
    for (size_t d = 1; d <= nn; d += 2) {
        for (size_t m = d; m <= nn; m += d)
            odddiv[m]++;
    }

    /* Main convolution loop */
    for (size_t s = 1; s <= nn; ++s) {
        int c = (s & 1) ? 2 * odddiv[s] : odddiv[s >> 1];
        if (c == 0) continue;
        for (int t = 0; t < c; ++t) {
            for (size_t i = nn; i >= s; --i) {
                /* multiply by (1 - q^s) once */
                dp[i] += -(dp[i - s]);
            }
        }
    }

    seq_t result = dp[n];

    free(dp);
    free(odddiv);
    return result;
}
